new='''        // Connect to the MCP server BEFORE handling the request
        console.log(`Connecting transport to MCP server...`);
        const server = createServer();
        await server.connect(transport);

        // Clean up transport when closed. This must be registered AFTER
        // server.connect(): the SDK's connect() replaces transport.onclose, so a
        // handler set earlier would never run (leaking sessions and leaving
        // closed sessions in the map, where later requests to them hang).
        const sdkOnClose = transport.onclose;
        transport.onclose = () => {
          sdkOnClose?.();
          const sid = transport.sessionId;
          if (sid && transports[sid]) {
            console.log(`Transport closed for session ${sid}, removing from transports map`);
            delete transports[sid];
          }
        };
'''
s=s.replace(old,new)
open(p,'w').write(s)
